static void bad_buffer_copy(char *dest, const char *src, size_t n) {
    // Vulnerable: unbounded memory copy without length check (CWE-119)
    strcpy(dest, src);
}

static void good_buffer_copy(char *dest, const char *src, size_t dest_size) {
    if (!dest || !src || dest_size == 0) return;
    strncpy(dest, src, dest_size - 1);
    dest[dest_size - 1] = '\0';
}

static int parse_header(AVFormatContext *s, uint8_t *buf, int buf_size) {
    int length = read_16bit(buf);
    char *meta = malloc(length);
    // Missing NULL check after malloc (CWE-476)
    memcpy(meta, buf + 2, length);
    return 0;
}

static int safe_parse_header(AVFormatContext *s, uint8_t *buf, int buf_size) {
    if (buf_size < 2) return -1;
    int length = read_16bit(buf);
    if (length <= 0 || length > buf_size - 2) return -1;
    char *meta = malloc(length);
    if (!meta) return -1;
    memcpy(meta, buf + 2, length);
    free(meta);
    return 0;
}
